Method.Implementation:
Set PID3Cnt = pSource.GetValueAt("PID:3(*)")
Set UnitNum = ""
for i=1:1:PID3Cnt
{
	//Get 
	Set aaNm = pSource.GetValueAt("PID:3("_i_").4.1")
	If aaNm = "UN"
	{
		Set UnitNum = pSource.GetValueAt("PID:3("_i_").1")
		Quit
	}
}
Quit UnitNum

Set status = $$$OK Set out = "" try{ Set expX = ##class(%Regex.Matcher).%New("XX+") Set expS = ##class(%Regex.Matcher).%New(" +") Set expX.Text = input Set out = expX.ReplaceAll("") Set expS.Text = out Set out = expS.ReplaceAll(" ") } Catch(e) { Set out = input Do $System.Status.DecomposeStatus(%objlasterror,.Err) Set status = $$$ERROR($$$GeneralError,"Exception in replaceMatchedRegexPattern method of IHC.ITF.Transform.Util.GenericDemogrHl7ToUsiisRegex error : value "_input_" , Error message : "_Err(Err))
;W err,!
} Quit status

